def lengthen_articles(apps, schema_editor):
    WellnessArticleSource = apps.get_model("teumteum", "WellnessArticleSource")

    for article in UPDATED_ARTICLES:
        WellnessArticleSource.objects.filter(
            source=article["source"]
        ).update(content=article["content"])


